style.css:
/* Selects all paragraph elements and sets their text color to blue, font size to 16 pixels, and adds a margin at the bottom */
p {
  color: blue;
  font-size: 16px;
  margin-bottom: 10px;
}

/* Selects all heading level 1 elements and centers their text, changes font family, and sets background color */
h1 {
  text-align: center;
  font-family: Arial, sans-serif;
  background-color: lightgray;
}
